const snippets={"Python": ["from typing import Optional", "", "class Solution:", "", "    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:", "        dummy = ListNode()", "        (carry, curr) = (0, dummy)", "        while l1 or l2 or carry:", "            s = (l1.val if l1 else 0) + (l2.val if l2 else 0) + carry", "            (carry, val) = divmod(s, 10)", "            curr.next = ListNode(val)", "            curr = curr.next", "            l1 = l1.next if l1 else None", "            l2 = l2.next if l2 else None", "        return dummy.next"], "Java": ["import java.util.*;", "class Solution {", "    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {", "        ListNode dummy = new ListNode(0);", "        int carry = 0;", "        ListNode cur = dummy;", "        while (l1 != null || l2 != null || carry != 0) {", "            int s = (l1 == null ? 0 : l1.val) + (l2 == null ? 0 : l2.val) + carry;", "            carry = s / 10;", "            cur.next = new ListNode(s % 10);", "            cur = cur.next;", "            l1 = l1 == null ? null : l1.next;", "            l2 = l2 == null ? null : l2.next;", "        }", "        return dummy.next;", "    }", "}"]};
